package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

var (
	uploadDir  = "/var/data/uploads"
	sessionMu  sync.RWMutex
	sessions   = make(map[string]string)
)

func generateToken() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	user := r.FormValue("username")
	pass := r.FormValue("password")
	// Simplified auth - in production this hits LDAP
	if user == "admin" && pass == os.Getenv("ADMIN_PASS") {
		token := generateToken()
		sessionMu.Lock()
		sessions[token] = user
		sessionMu.Unlock()
		http.SetCookie(w, &http.Cookie{Name: "session", Value: token, Path: "/"})
		w.Write([]byte("OK"))
		return
	}
	http.Error(w, "Unauthorized", 401)
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		cookie, err := r.Cookie("session")
		if err != nil {
			http.Error(w, "Unauthorized", 401)
			return
		}
		sessionMu.RLock()
		_, ok := sessions[cookie.Value]
		sessionMu.RUnlock()
		if !ok {
			http.Error(w, "Unauthorized", 401)
			return
		}
		next(w, r)
	}
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}
	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "Bad request", 400)
		return
	}
	defer file.Close()

	// Generate unique filename preserving extension
	ext := filepath.Ext(header.Filename)
	newName := fmt.Sprintf("%d_%s%s", time.Now().UnixNano(), generateToken()[:8], ext)
	dstPath := filepath.Join(uploadDir, newName)

	dst, err := os.Create(dstPath)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer dst.Close()
	io.Copy(dst, file)

	w.Write([]byte(fmt.Sprintf("Uploaded: %s", newName)))
}

func convertHandler(w http.ResponseWriter, r *http.Request) {
	filename := r.URL.Query().Get("file")
	format := r.URL.Query().Get("format")

	if filename == "" || format == "" {
		http.Error(w, "Missing parameters", 400)
		return
	}

	// Basic validation - only allow alphanumeric, dots, underscores, hyphens
	for _, c := range filename {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-') {
			http.Error(w, "Invalid filename", 400)
			return
		}
	}

	// Validate format parameter allows only specific conversions
	allowedFormats := []string{"pdf", "png", "jpg", "docx"}
	formatValid := false
	for _, f := range allowedFormats {
		if strings.EqualFold(format, f) {
			formatValid = true
			break
		}
	}
	if !formatValid {
		http.Error(w, "Invalid format", 400)
		return
	}

	srcPath := filepath.Join(uploadDir, filename)
	if _, err := os.Stat(srcPath); os.IsNotExist(err) {
		http.Error(w, "File not found", 404)
		return
	}

	outName := strings.TrimSuffix(filename, filepath.Ext(filename)) + "." + format
	outPath := filepath.Join(uploadDir, outName)

	// Use LibreOffice for document conversion
	cmd := exec.Command("libreoffice", "--headless", "--convert-to", format, "--outdir", uploadDir, srcPath)
	cmd.Env = append(os.Environ(), "HOME=/tmp")
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("Conversion failed: %s", string(output)), 500)
		return
	}

	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%s", outName))
	http.ServeFile(w, r, outPath)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("OK"))
}

func main() {
	os.MkdirAll(uploadDir, 0755)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/login", loginHandler)
	http.HandleFunc("/upload", authMiddleware(uploadHandler))
	http.HandleFunc("/convert", authMiddleware(convertHandler))
	http.ListenAndServe(":8080", nil)
}
